// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

// A Worker runs in front of Cloudflare's CDN, so the s-maxage on /api/catalog/*
// isn't honoured on its own. Keep those GETs in the colo cache, as Vercel's CDN
// did. The Cache API is a no-op on *.workers.dev; it works on the custom domain.
// ponytail: no stale-while-revalidate, so a miss after 60s waits on Supabase.
export default {
  async fetch(request: Request, env: unknown, ctx: { waitUntil(promise: Promise<unknown>): void }) {
    const url = new URL(request.url);
    if (request.method !== "GET" || !url.pathname.startsWith("/api/catalog/")) {
      return handler.fetch(request, env, ctx);
    }

    const cache = (caches as unknown as { default: Cache }).default;
    const hit = await cache.match(request);
    if (hit) return hit;

    const response: Response = await handler.fetch(request, env, ctx);
    if (response.ok) ctx.waitUntil(cache.put(request, response.clone()));
    return response;
  }
};
